from pathlib import Path
import re
r=Path(__file__).resolve().parent
p=r/'public'
logo='<img class="brand-logo" src="/assets/logo-tuan-beo.webp" width="80" height="80" alt="Logo Y học cổ truyền – Giải cơ sâu">'
for f in p.glob('*.html'):
 t=f.read_text()
 t=re.sub(r'<span class="seal"[^>]*>T</span>',logo,t)
 t=t.replace('<link rel="icon" href="/assets/favicon.svg" type="image/svg+xml">','<link rel="icon" href="/assets/logo-tuan-beo.webp" type="image/webp"><link rel="apple-touch-icon" href="/assets/logo-tuan-beo.png">')
 if 'og:image' not in t:
  t=t.replace('</head>','<meta property="og:image" content="https://trilieutuanbeo.vercel.app/assets/logo-social.jpg"><meta property="og:image:alt" content="Tuấn Béo – Y học cổ truyền, Giải cơ sâu"><meta name="twitter:card" content="summary_large_image"></head>')
 t=t.replace('Chữ T trên website là ký hiệu trình bày tạm thời, không phải logo chính thức.','Logo do chủ website cung cấp ngày 16/10/2026; đã xử lý nền để hiển thị trên giao diện.')
 t=t.replace('logo chính thức chưa được xác minh.','logo được sử dụng từ tệp chủ website cung cấp.')
 t=t.replace('/assets/phong-tri-lieu.jpg','/assets/phong-tri-lieu-enhanced.webp').replace('/assets/tiep-khach.jpg','/assets/tiep-khach-enhanced.webp')
 if f.name=='index.html' and 'brand-signature' not in t:
  t=t.replace('<div class="hero-art reveal">','<div class="hero-art reveal"><div class="hero-emblem">'+logo+'</div>')
  t=t.replace('<section id="gioi-thieu">','<section class="brand-signature"><div class="wrap signature-inner"><img src="/assets/logo-tuan-beo.webp" width="220" height="220" alt="Biểu trưng bàn tay, bó cơ, hoa sen và thảo mộc"><div><span class="eyebrow">Y HỌC CỔ TRUYỀN · GIẢI CƠ SÂU</span><h2>Bàn tay chăm sóc.<br>Tinh thần dưỡng sinh.</h2><p>Tuấn Béo đồng hành cùng bạn trong việc tìm hiểu cơ thể, lựa chọn phương pháp chăm sóc phù hợp và nuôi dưỡng những thói quen tốt mỗi ngày.</p><a class="textlink" href="#dich-vu">Tìm hiểu dịch vụ của Tuấn Béo ↗</a></div></div></section><section id="gioi-thieu">')
  t=t.replace('</div><div class="map-actions">','</div><div class="map-actions">')
  t=t.replace('Ảnh do cơ sở đăng trên Google Maps','Ảnh cơ sở từ Google Maps · đã cân chỉnh bằng AI')
  t=t.replace('</main><footer>','<dialog id="photo-viewer" aria-label="Xem ảnh không gian"><button class="photo-close" autofocus aria-label="Đóng ảnh">Đóng ×</button><img alt=""><p></p></dialog></main><footer>') if 'photo-viewer' not in t else t
 t=t.replace('Hình công cụ vẫn là minh họa danh mục','Ảnh phòng đã được hỗ trợ cân chỉnh ánh sáng và giảm nhiễu bằng AI; ảnh gốc được lưu để đối chiếu. Hình công cụ vẫn là minh họa danh mục') if f.name=='nguon-du-lieu.html' and 'giảm nhiễu bằng AI' not in t else t
 f.write_text(t)
css='''
/* Brand identity from supplied logo */
:root{--green:#263f32;--ink:#293c2f;--cream:#faf6ed;--gold:#987329;--lotus:#b76f73;--herb:#73824d;--line:#ddd8c8}body{background:var(--cream)}header{background:#faf6edf5}.brand-logo{width:80px;height:80px;object-fit:contain;flex-shrink:0}.brand{gap:14px}.brand strong{font-weight:500}.brand small{letter-spacing:1.5px}nav{min-height:104px}.hero{gap:60px;padding-top:54px}.hero-art{border:1px solid #c5a459;border-radius:180px 180px 12px 12px;box-shadow:0 20px 50px #283d301a;overflow:visible;background:#eee9dc}.real-hero{border-radius:180px 180px 12px 12px;object-position:center}.hero-emblem{position:absolute;right:-20px;top:34px;z-index:1;border-radius:50%;background:#faf6ed;box-shadow:0 6px 28px #263f3226;padding:8px;border:1px solid #d6bf85}.hero-emblem .brand-logo{width:116px;height:116px;display:block}.art-label{border-radius:5px;backdrop-filter:blur(8px)}.brand-signature{background:linear-gradient(120deg,#ebe8d9,#f7f0e6);border-bottom:1px solid var(--line);padding:54px 0}.signature-inner{display:grid;grid-template-columns:240px 1fr;align-items:center;gap:76px;max-width:1000px}.signature-inner>img{width:100%;height:auto;filter:drop-shadow(0 8px 14px #98732919)}.signature-inner h2{font-size:36px;margin:10px 0 18px}.signature-inner p{margin:0}.service-card{border-radius:10px;border-top:3px solid #b49858;box-shadow:0 6px 20px #293c2f05;transition:transform .3s,box-shadow .3s}.service-card:hover{transform:translateY(-4px);box-shadow:0 14px 28px #293c2f10}.service-card:nth-child(2n){border-top-color:var(--lotus)}.space-image{height:auto;max-height:420px;object-fit:contain;background:#eee8da;box-shadow:0 12px 32px #293c2f14}.space-gallery{align-items:start;grid-template-columns:1fr 1fr}.space-gallery figure{padding:12px;background:#fffdf7;border:1px solid var(--line);border-radius:12px;box-shadow:0 10px 25px #293c2f0b}.space-gallery img{height:420px;background:#f0ecdf;border-radius:6px;cursor:zoom-in}.space-gallery figcaption{padding:0 8px;font-size:13px}.photo-open{display:block;background:none;border:0;padding:0;width:100%}.photo-open:after{content:'Xem ảnh lớn ↗';display:block;font-size:13px;color:var(--green);text-align:right;padding:10px 6px 0}#photo-viewer{max-width:min(920px,94vw);max-height:94vh;padding:18px;background:var(--cream);border:1px solid #b49858;border-radius:12px}#photo-viewer::backdrop{background:#11261ee8;backdrop-filter:blur(4px)}#photo-viewer img{display:block;max-height:73vh;max-width:100%;margin:auto;object-fit:contain}#photo-viewer p{font-size:13px;margin:12px auto 0}.photo-close{display:block;margin:0 0 14px auto;background:var(--green);color:white;border:0;border-radius:4px;padding:8px 18px}footer .brand-logo{background:#faf6ed;border-radius:50%;padding:4px;width:100px;height:100px}footer .brand{min-width:265px}.dark{background:radial-gradient(ellipse at top right,#3b523b,#203b2d)}.dark .number{color:#d4b66a}.button{border-radius:6px}.call-float{background:var(--green)}@media(max-width:1050px){.brand-logo{width:64px;height:64px}.navlinks{gap:12px}.brand strong{font-size:22px}.navlinks a{font-size:12px}.hero-emblem{right:-8px}.hero-emblem .brand-logo{width:90px;height:90px}}@media(max-width:720px){nav{min-height:90px}.brand-logo{width:64px;height:64px}.navlinks{top:90px}.navlinks a{font-size:16px}.hero{gap:38px}.hero-emblem{right:8px;top:20px}.hero-emblem .brand-logo{width:82px;height:82px}.signature-inner{grid-template-columns:1fr;gap:24px;text-align:center}.signature-inner>img{width:180px;margin:auto}.signature-inner h2{font-size:30px}.signature-inner p{font-size:16px}.space-gallery{grid-template-columns:1fr}.space-gallery img{height:auto;max-height:480px}.brand-signature{padding:40px 0}footer .brand{margin-bottom:24px}.real-hero{height:500px}}@media(prefers-reduced-motion:reduce){.service-card{transition:none}.service-card:hover{transform:none}}
'''
f=p/'styles.css';f.write_text(f.read_text().split('/* Brand identity from supplied logo */')[0]+css)
js='''
/* Accessible facility photo viewer */
const viewer=document.querySelector('#photo-viewer');if(viewer){let photoTrigger;document.querySelectorAll('.space-gallery figure').forEach(figure=>{const img=figure.querySelector('img');if(!img||img.closest('button'))return;const button=document.createElement('button');button.className='photo-open';button.setAttribute('aria-label','Xem ảnh lớn: '+img.alt);img.before(button);button.append(img);button.addEventListener('click',()=>{photoTrigger=button;viewer.querySelector('img').src=img.src;viewer.querySelector('img').alt=img.alt;viewer.querySelector('p').textContent=figure.querySelector('figcaption')?.textContent||img.alt;viewer.showModal()})});viewer.querySelector('.photo-close').addEventListener('click',()=>viewer.close());viewer.addEventListener('click',e=>{if(e.target===viewer)viewer.close()});viewer.addEventListener('close',()=>photoTrigger?.focus())}
'''
f=p/'app.js';f.write_text(f.read_text().split('/* Accessible facility photo viewer */')[0]+js)
